class Solution {
public:
    bool areOccurrencesEqual(string s) {
        unordered_map<char, int> count;
        for (char c : s) count[c]++;
        int target = -1;
        for (auto& [ch, num] : count) {
            if (target == -1) target = num;
            else if (num != target) return false;
        }
        return true;
    }
};

