class Solution:
    def areOccurrencesEqual(self, s: str) -> bool:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1
        target = 0
        for c in cnt:
            if c == 0:
                continue
            if target == 0:
                target = c
            elif c != target:
                return False
        return True

