        for (char c : s) cnt[c - 'a']++;
        int target = 0;
        for (int i = 0; i < 26; i++) {
            if (cnt[i] == 0) continue;
            if (target == 0) target = cnt[i];
            else if (cnt[i] != target) return false;
        }
        return true;
    }
};

